E        +    where {'Error': {'Code': '403', 'Message': 'Forbidden'}, 'ResponseMetadata': {'RequestId': '28D05F514E474F0E8C001CF1171020B4...quest-id': '28D05F514E474F0E8C001CF1171020B4', 'content-length': '247', 'date': 'Fri, 23 Oct 2026 13:46:47 GMT'}, ...}} = ClientError('An error occurred (403) when calling the HeadObject operation: Forbidden').response

